--- assistant 1
<write path="canon/service.cn">
type AcceptTermsInput {
  email: String,
  accepted: Bool,
}

type AcceptTermsError =
  | InvalidEmail(String)
  | NotAccepted

api fn accept_terms(input: AcceptTermsInput) -> Result[AcceptTermsInput, AcceptTermsError]
  route: POST "/terms"
  effects: io
  requires: is_email(input.email) && input.accepted
{
  return Ok(input)
}
</write>

<write path="frontend/src/features/acceptTerms.ts">
import { createClient } from "../canon/client";
import type { Outcome } from "./result";

/** Record that a user accepted the terms. */
export async function acceptTerms(baseUrl: string, input: { email: string; accepted: boolean }): Promise<Outcome<{ email: string; accepted: boolean }>> {
  const client = createClient(baseUrl);
  if (!input.accepted) {
    return { ok: false, error: { kind: "ValidationError", rule: "accepted" } };
  }
  const result = await client.acceptTerms({ email: input.email, accepted: input.accepted });
  if (result.ok) {
    return { ok: true, value: result.value };
  } else {
    return { ok: false, error: { kind: "ValidationError", rule: "email" } };
  }
}
</write>

