<write path="canon/service.cn">
type Booking {
  guest: String,
  start: Int,
  end: Int,
  nights: Int,
}

type BookingError =
  | InvalidInput(error: String)

api fn book_stay(input: { guest: String; start: Int; end: Int }) -> Result[Booking, BookingError]
  route: POST "/bookings"
  effects: io
  requires: str_len(trim(input.guest)) > 0 && input.start >= 0 && input.start <= 365 && input.end > input.start && input.end - input.start <= 30
{
  let nights = input.end - input.start
  let booking = Booking { guest: input.guest, start: input.start, end: input.end, nights: nights }
  print(booking)
  return Ok(booking)
}
</write>

<write path="frontend/src/features/bookStay.ts">
import { createClient } from "../canon/client";
import type { Outcome } from "./result";

/** Book a stay. */
export async function bookStay(baseUrl: string, input: { guest: string; start: number; end: number }): Promise<Outcome<{ guest: string; start: number; end: number; nights: number }>> {
  const client = createClient(baseUrl);
  if (str_len(trim(input.guest)) === 0 || input.start < 0 || input.start > 365 || input.end <= input.start || input.end - input.start > 30) {
    return { ok: false, error: { kind: "ValidationError" } };
  }
  return client.bookStay({ guest: input.guest, start: input.start, end: input.end });
}
</write>

