    def code_must_be_between_3_and_20_chars(cls, v):
        if not (3 <= len(v) <= 20):
            raise HTTPException(status_code=422, detail="code must be between 3 and 20 characters")
        return v

    @validator('subtotal')
    def subtotal_must_be_at_least_1(cls, v):
        if v < 1:
            raise HTTPException(status_code=422, detail="subtotal must be at least 1")
        return v

    @validator('discount')
    def discount_must_be_between_0_and_subtotal(cls, v, values):
        if v < 0 or v > values['subtotal']:
            raise HTTPException(status_code=422, detail="discount must be between 0 and subtotal")
        return v

