import { call, invalid } from "../api/client";
import type { Outcome } from "./result";

export interface ApplyCouponInput {
  code: string;
  subtotal: number;
  discount: number;
}

export interface ApplyCouponOutput {
  code: string;
  subtotal: number;
  discount: number;
  payable: number;
}

export async function applyCoupon(baseUrl: string, input: ApplyCouponInput): Promise<Outcome<ApplyCouponOutput>> {
