    return invalid("subtotal must be at least 1");
  }
  if (input.discount < 0 || input.discount > input.subtotal) {
    return invalid("discount must be between 0 and subtotal");
  }
  return call<ApplyCouponOutput>(baseUrl, "POST", "/coupons/apply", input);
