from fastapi.responses import JSONResponse
from pydantic import BaseModel
from typing import List, Optional

from ..models import Poll, PollError, NewPoll
from ..store import polls

router = APIRouter()

class Pong(BaseModel):
    ok: bool

@router.get("/ping", response_model=Pong)
async def ping():
    return Pong(ok=True)

class PollResponse(BaseModel):
    question: str
    options: List[str]

@router.post("/polls", response_model=PollResponse)
async def create_poll(input: NewPoll):
    if len(input.question.strip()) < 5 or len(input.question.strip()) > 120 or len(input.options) < 2 or len(input.options) > 6:
        raise HTTPException(status_code=422, detail={"kind": "ValidationError", "rule": "requires"})
    poll = Poll(id=next_id(polls), question=input.question.strip(), options=input.options)
    insert(polls, poll)
    return PollResponse(question=poll.question, options=poll.options)

def next_id(table):
    return len(table) + 1

def insert(table, row):
    table[row.id] = row
