    def check_color(cls, v):
        if v not in ['red', 'green', 'blue', 'gray']:
            raise InvalidRequest("color must be one of 'red', 'green', 'blue', 'gray'")
        return v

@app.post("/tags")
async def create_tag(tag: TagCreate) -> TagCreate:
    return tag
