        if not v.strip():
            raise InvalidRequest("title must not be blank")
        if len(v) > 60:
            raise InvalidRequest("title must be at most 60 characters")
        return v


app = FastAPI(title="forms")
install_error_handlers(app)


@app.get("/ping")
def ping() -> dict[str, bool]:
    return {"ok": True}


@app.post("/events/ages")
