  min_age: Int,
  max_age: Int,
  title: String,
}

type AgeRangeError =
  | InvalidAgeRange(min_age: Int, max_age: Int)
  | InvalidTitle(title: String)

api fn set_age_range(input: AgeRange) -> Result[AgeRange, AgeRangeError]
  route: POST "/events/ages"
  effects: io
  requires: input.min_age >= 0 && input.min_age <= 120 && input.max_age >= 0 && input.max_age <= 120 && input.max_age >= input.min_age && str_len(trim(input.title)) > 0 && str_len(trim(input.title)) <= 60
