import { createClient } from "../canon/client";
import type { Outcome } from "./result";

/** Set the age range of an event. */
export async function setAgeRange(baseUrl: string, input: { min_age: number; max_age: number; title: string }): Promise<Outcome<{ min_age: number; max_age: number; title: string }>> {
  const client = createClient(baseUrl);
  if (input.min_age < 0 || input.min_age > 120 || input.max_age < 0 || input.max_age > 120 || input.max_age < input.min_age || input.title.trim().length === 0 || input.title.trim().length > 60) {
    return { ok: false, error: { kind: "ValidationError", rule: "Invalid input" } };
  }
  return client.setAgeRange({ min_age: input.min_age, max_age: input.max_age, title: input.title });
}
