import { createClient } from "../canon/client";
import type { Outcome } from "./result";

/** Set a budget allocation. */
export async function setAllocation(baseUrl: string, input: { ads: number; dev: number; ops: number; project: string }): Promise<Outcome<{ ads: number; dev: number; ops: number; project: string }>> {
  const client = createClient(baseUrl);
  const ads = Math.floor(input.ads);
  const dev = Math.floor(input.dev);
  const ops = Math.floor(input.ops);
  const project = input.project.trim();

  if (ads < 0 || ads > 100 || dev < 0 || dev > 100 || ops < 0 || ops > 100 || ads + dev + ops !== 100 || project.length < 1 || project.length > 30) {
    return { ok: false, error: { kind: "ValidationError" } };
  }

  try {
    const response = await client.setAllocation({ ads, dev, ops, project });
    return { ok: true, value: response };
  } catch (error) {
    return { ok: false, error: { kind: "AllocationError", message: error.message } };
  }
}
</write>

