from fastapi import APIRouter, Depends, HTTPException
from fastapi.responses import JSONResponse
from pydantic import BaseModel
from typing import List, Optional
from canon_generated.logic import create_donation
from canon_generated.models import Donation, DonationError

router = APIRouter()

class DonationRequest(BaseModel):
    amount: float
    currency: str
    anonymous: bool

@router.post("/donations", response_model=Donation)
async def create_donation_route(request: DonationRequest):
    try:
        result = create_donation(Donation(amount=request.amount, currency=request.currency, anonymous=request.anonymous))
        if result.is_err():
            error = result.unwrap_err()
            if isinstance(error, DonationError.InvalidAmount):
                raise HTTPException(status_code=422, detail={"error": {"kind": "ValidationError", "rule": "amount"}})
            elif isinstance(error, DonationError.InvalidCurrency):
                raise HTTPException(status_code=422, detail={"error": {"kind": "ValidationError", "rule": "currency"}})
        return result.unwrap()
    except Exception as e:
        raise HTTPException(status_code=500, detail={"error": {"kind": "InternalError", "message": str(e)}})

class Pong(BaseModel):
    ok: bool

@router.get("/ping", response_model=Pong)
async def ping():
    return Pong(ok=True)
</write>

<write path="frontend/src/canon/client.ts">
import { createClient } from "./client";
import type { Outcome } from "./validate";

/** Check that the service is up. */
export async function ping(baseUrl: string): Promise<Outcome<{ ok: boolean }>> {
  return createClient(baseUrl).ping();
}

/** Make a donation. */
export async function create_donation(baseUrl: string, input: { amount: number; currency: string; anonymous: boolean }): Promise<Outcome<{ amount: number; currency: string; anonymous: boolean }>> {
  const client = createClient(baseUrl);
  if (input.amount < 1.0 || input.amount > 5000.0) {
    return { ok: false, error: { kind: "ValidationError", rule: "amount" } };
  }
  if (input.currency !== "USD" && input.currency !== "EUR") {
    return { ok: false, error: { kind: "ValidationError", rule: "currency" } };
  }
  try {
    const response = await client.createDonation(input);
    if (response.ok) {
      return { ok: true, value: response.value };
    } else {
      return { ok: false, error: { kind: "ValidationError", rule: response.error.rule } };
    }
  } catch (error) {
    return { ok: false, error: { kind: "InternalError", message: error.message } };
  }
}
</write>

